  def genTestCase(observationKind: ObservationKind.Type, preContainer: Option[String], postContainer: Option[String], testNameSuffix: Option[String]): ST = {
    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {
      case dual_zone_greenhouse.runtimemonitor.ObservationKind.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_postInit =>
        return (st"""// Begin test cases for Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_postInit
                    |
                    |test(s"Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_postInit: Check Post-condition$suffix") {
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val postContainer = dual_zone_greenhouse.JSON.toDual_Zone_GreenhouseZone_A_Sensor_Intake_i_control_process_zone_a_sensor_intake_PostState_Container_PS(postJson).left
                    |  assert(dual_zone_greenhouse.Dual_Zone_Greenhouse.Zone_A_Sensor_Intake_i_control_process_zone_a_sensor_intake_GumboX.inititialize_IEP_Post_Container(postContainer))
                    |}
                    |// End test cases for Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_postInit""")
      case dual_zone_greenhouse.runtimemonitor.ObservationKind.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_preCompute =>
        return (st"""// Begin test cases for Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_preCompute
                    |
                    |test(s"Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_preCompute: Check Pre-condition$suffix") {
                    |  val preJson: String = st${tq}${preContainer.get}${tq}.render
                    |  val preContainer = dual_zone_greenhouse.JSON.toDual_Zone_GreenhouseZone_A_Sensor_Intake_i_control_process_zone_a_sensor_intake_PreState_Container_PS(preJson).left
                    |  if (verbose) {
                    |    println("Pre-State Values:")
                    |    println(s"  $$preContainer")
                    |  }
                    |  assert(dual_zone_greenhouse.Dual_Zone_Greenhouse.Zone_A_Sensor_Intake_i_control_process_zone_a_sensor_intake_GumboX.compute_CEP_Pre_Container(preContainer))
                    |}
                    |// End test cases for Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_preCompute""")
      case dual_zone_greenhouse.runtimemonitor.ObservationKind.Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_postCompute =>
        return (st"""// Begin test cases for Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_postCompute
                    |
                    |test(s"Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_postCompute: Check Pre-condition$suffix") {
                    |  val preJson: String = st${tq}${preContainer.get}${tq}.render
                    |  val preContainer = dual_zone_greenhouse.JSON.toDual_Zone_GreenhouseZone_A_Sensor_Intake_i_control_process_zone_a_sensor_intake_PreState_Container_PS(preJson).left
                    |  if (verbose) {
                    |    println("Pre-State Values:")
                    |    println(s"  $$preContainer")
                    |  }
                    |  assert(dual_zone_greenhouse.Dual_Zone_Greenhouse.Zone_A_Sensor_Intake_i_control_process_zone_a_sensor_intake_GumboX.compute_CEP_Pre_Container(preContainer))
                    |}
                    |
                    |test(s"Dual_Zone_Greenhouse_Root_Instance_control_process_zone_a_sensor_intake_postCompute: Check Post-condition$suffix") {
                    |  val preJson: String = st${tq}${preContainer.get}${tq}.render
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val preContainer = dual_zone_greenhouse.JSON.toDual_Zone_GreenhouseZone_A_Sensor_Intake_i_control_process_zone_a_sensor_intake_PreState_Container_PS(preJson).left
                    |  val postContainer = dual_zone_greenhouse.JSON.toDual_Zone_GreenhouseZone_A_Sensor_Intake_i_control_process_zone_a_sensor_intake_PostState_Container_PS(postJson).left
